//###########################################################
countTradeResults = function(infoObjs, isLong, ignoreWithWarning = true) {
  var el, j, len, totalTrades, winTrades;
  winTrades = 0;
  totalTrades = 0;
  for (j = 0, len = infoObjs.length; j < len; j++) {
    el = infoObjs[j];
    if (ignoreWithWarning && el.warn) {
      continue;
    }
    totalTrades++;
    if (isLong && el.deltaF > 0.0) {
      winTrades++;
    } else if (!isLong && el.deltaF < 0.0) {
      winTrades++;
    }
  }
  return {winTrades, totalTrades};
};

