getSplitCorrectionFactor = function(splitFactors, dateYYYYMMDD) {
  var j, len, sf;
  if (!(splitFactors != null ? splitFactors.length : void 0)) {
    return 1;
  }
// splitFactors = [{f, applied, end: "YYYY-MM-DD"}, ...]
  for (j = 0, len = splitFactors.length; j < len; j++) {
    sf = splitFactors[j];
    if (dateYYYYMMDD <= sf.end || (sf.end == null)) {
      // our date is within range of this splitFactor
      if (sf.applied) {
        return sf.f;
      } else {
        return 1;
      }
    }
  }
  return 1;
};

//###########################################################
getAverageAndMedianChanges = function(infoObjs, ignoreWithWarning = true) {
  var avgChangeF, changeSum, el, factors, i, idx, j, len, medChangeF, num;
  // log "getAverageAndMedianChanges"
  changeSum = 0;
  factors = [];
  num = 0;
  for (i = j = 0, len = infoObjs.length; j < len; i = ++j) {
    el = infoObjs[i];
    if (ignoreWithWarning && el.warn) {
      continue;
    }
    changeSum += el.deltaF;
    factors.push(el.deltaF);
    num++;
  }
  // default to 1, 1 if we donot have a valid year
  if (num === 0) {
    return {
      avgChangeF: 1.0,
      medChangeF: 1.0
    };
  }
  avgChangeF = 1.0 * changeSum / num;
  factors.sort(function(a, b) {
    return a - b; // sort ascending for median
  });
  if (num % 2) { // odd case
    idx = (num - 1) / 2;
    medChangeF = factors[idx];
  } else {
    idx = num / 2;
    medChangeF = 0.5 * (factors[idx] + factors[idx - 1]);
  }
  return {avgChangeF, medChangeF};
};

