getMaxRiseAndMaxDrop = function(infoObjs, ignoreWithWarning = true) {
  var absMaxDropEl, absMaxRiseEl, el, j, len, maxDropEl, maxRiseEl;
  // log "getMaxRiseAndMaxDrop"
  maxRiseEl = {
    maxRiseF: -0.1
  };
  maxDropEl = {
    maxDropF: 0.1
  };
  absMaxRiseEl = {
    maxRiseAr: -0.1
  };
  absMaxDropEl = {
    maxDropAr: 0.1
  };
  for (j = 0, len = infoObjs.length; j < len; j++) {
    el = infoObjs[j];
    if (ignoreWithWarning && el.warn) {
      continue;
    }
    if (el.maxRiseF > maxRiseEl.maxRiseF) {
      maxRiseEl = el;
    }
    if (el.maxDropF < maxDropEl.maxDropF) {
      maxDropEl = el;
    }
    if (el.maxRiseAr > absMaxRiseEl.maxRiseAr) {
      absMaxRiseEl = el;
    }
    if (el.maxDropAr < absMaxDropEl.maxDropAr) {
      absMaxDropEl = el;
    }
  }
  return {maxRiseEl, maxDropEl, absMaxRiseEl, absMaxDropEl};
};

