evaluateTradableRun = function(runObj) {
  var close, closeDelta, closeDeltaF, endA, high, i, j, lastClose, low, maxDropA, maxRiseA, ref, seq, startA, warn;
  // log "evaluateTradableRun"
  seq = runObj.seq;
  // We start at end of day of the first trade and we leave at end of day of the last Tradeday
  startA = seq[0][seq[0].length - 1];
  if (startA !== runObj.entryCv) {
    console.error(`startA (${startA}) != entryCv (=${runObj.entryCv})`);
  }
  endA = seq[seq.length - 1][seq[seq.length - 1].length - 1];
  maxRiseA = startA; // day 0 entry as initial maxRise
  maxDropA = startA; // day 0 entry as initial maxDrop
  warn = false;
  lastClose = startA;
  for (i = j = 1, ref = seq.length; (1 <= ref ? j < ref : j > ref); i = 1 <= ref ? ++j : --j) {
    if (seq[i].length === 3) {
      high = seq[i][0];
      low = seq[i][1];
      close = seq[i][2];
    } else {
      continue; // same close no high, no low -> no update
    }
    if (high > maxRiseA) {
      maxRiseA = high;
    }
    if (low < maxDropA) {
      maxDropA = low;
    }
    // add a warning if any day to day difference is too much (+42.9% or -30%)
    closeDelta = close - lastClose;
    closeDeltaF = 1.0 * closeDelta / lastClose;
    warn = warn || closeDeltaF > 0.429 || closeDeltaF < -0.3;
    lastClose = close;
  }
  // Calculate facors to easily get the percentages deltas
  runObj.deltaF = (1.0 * endA / startA) - 1.0;
  runObj.maxRiseF = (1.0 * maxRiseA / startA) - 1.0;
  runObj.maxDropF = (1.0 * maxDropA / startA) - 1.0;
  
  // also for the absolut values wes use the deltas of the real absolute values
  runObj.maxRiseAr = 1.0 * (maxRiseA - startA) / runObj.corrSF;
  runObj.maxDropAr = 1.0 * (maxDropA - startA) / runObj.corrSF;
  
  // Notice: for now we donot consider the case when the split-factor changed during the sequence - we simply take the split-factor at the start of the sequence
  runObj.warn = warn;
};


