getTradableStartIndex = function(data, idx, prepone) {
  var safetyCount;
  // log "getTradableStartIndex"
  safetyCount = 32;
  while (true) {
    if (--safetyCount < 0) { // prevent infinite loops
      console.error("getTradableStartIndex reached safety Limit!");
      return -1;
    }
    if (!Array.isArray(data[idx])) {
      return -1;
    }
    if (data[idx].length > 1) {
      return idx;
    }
    if (prepone) {
      idx--;
    } else {
      idx++;
    }
  }
  return -1;
};

//###########################################################
getTradableEndIndex = function(data, idx, postpone) {
  var safetyCount;
  // log "getTradableEndIndex"
  safetyCount = 32;
  while (true) {
    if (--safetyCount < 0) { // prevent infinite loops
      console.error("getTradableEndIndex reached safety Limit!");
      return idx; // fallback
    }
    if (!Array.isArray(data[idx])) {
      return -1;
    }
    if (data[idx].length > 1) {
      return idx;
    }
    if (postpone) {
      idx++;
    } else {
      idx--;
    }
  }
  return idx;
};
